/* Offline mixer. Chapter changes fade to silence before the next fade-in. */
class Atmosphere {
 constructor(onError){this.onError=onError;this.buffers=new Map();this.loading=new Map();this.active=[];this.tails=new Set();this.effects=new Set();this.scene='silence';this.enabled=false;this.paused=false;this.ambient=Atmosphere.ambientGain(10);this.fx=.15;this.effectsEnabled=true;this.token=0;this.chapterChanging=false;this.wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));}
 static triggerLine(height){return Math.min(height*.86,height-72);}
 static crossfadeSeconds(){return 2.4;}
 static hold(param,now){const value=param.value;if(param.cancelAndHoldAtTime)param.cancelAndHoldAtTime(now);else{param.cancelScheduledValues?.(now);param.setValueAtTime(value,now);}return value;}
 static ramp(param,from,to,now,seconds,rising){param.setValueAtTime(from,now);for(let i=1;i<=64;i++){const t=i/64,value=i===64?to:rising?to*Math.sin(t*Math.PI/2):from*Math.cos(t*Math.PI/2);param.linearRampToValueAtTime(value,now+seconds*t);}}

 static ambientGain(value){return .5*Math.pow(Math.max(0,Math.min(70,Number(value)||0))/100,1.7);}
 static layersFor(scene){return {city:[['city',1.5,6500]],idle:[['train-idle',.9,3500]],platform:[['train-idle',.45,2500],['snowfall',.85,2400]],train:[['train',.9]],fire:[['fire',.85]],wind:[['winter-air',2.8,850]],shelter:[['snowfall',.42,1000]],still:[['snowfall',.65,1700]],tension:[['fire',.55,3000]]}[scene]||[];}
 async init(){if(!this.ctx){this.ctx=new (window.AudioContext||window.webkitAudioContext)();this.master=this.ctx.createGain();this.master.gain.value=.9;const limiter=this.ctx.createDynamicsCompressor();limiter.threshold.value=-6;limiter.knee.value=8;limiter.ratio.value=2;limiter.attack.value=.01;limiter.release.value=.25;this.master.connect(limiter);limiter.connect(this.ctx.destination);}if(this.ctx.state==='suspended')await this.ctx.resume();}
 configure(settings){this.ambient=Atmosphere.ambientGain(settings.ambient);this.fx=settings.effects/100;this.effectsEnabled=settings.effectsEnabled;if(!this.effectsEnabled)this.stopEffects();for(const track of this.active)track.gain.gain.setTargetAtTime(this.ambient*track.level,this.ctx.currentTime,.18);}
 async buffer(name){if(this.buffers.has(name))return this.buffers.get(name);if(this.loading.has(name))return this.loading.get(name);const extension=name==='snowfall'?'wav':'mp3';const task=(async()=>{const response=await fetch(`assets/${name}.${extension}`);if(!response.ok)throw Error(name);const buffer=await this.ctx.decodeAudioData(await response.arrayBuffer());this.buffers.set(name,buffer);return buffer;})();this.loading.set(name,task);try{return await task;}finally{this.loading.delete(name);}}
 makeLoop(raw,key){const rate=raw.sampleRate,total=Math.min(raw.length,Math.floor(48*rate)),overlap=Math.min(Math.floor(rate*3.5),Math.floor(total/4)),length=total-overlap,loop=this.ctx.createBuffer(raw.numberOfChannels,length,rate);for(let ch=0;ch<raw.numberOfChannels;ch++){const input=raw.getChannelData(ch),output=loop.getChannelData(ch);output.set(input.subarray(overlap,total));for(let i=0;i<overlap;i++){const t=i/overlap;output[length-overlap+i]=input[total-overlap+i]*Math.cos(t*Math.PI/2)+input[i]*Math.sin(t*Math.PI/2);}}this.buffers.set(key+'-loop',loop);return loop;}
 async loop(name){if(this.buffers.has(name+'-loop'))return this.buffers.get(name+'-loop');const loop=this.makeLoop(await this.buffer(name),name);this.buffers.delete(name);return loop;}
 async prepare(scene){return Promise.all(Atmosphere.layersFor(scene).map(async([name,level,cutoff=12500])=>({name,level,cutoff,buffer:await this.loop(name)})));}
 dispose(track){if(track.disposed)return;track.disposed=true;try{track.source.stop();}catch{}try{track.gain.disconnect();track.filter?.disconnect();}catch{}this.tails.delete(track);}
 fadeOut(seconds=.8){this.playingScene=null;this.fadeTracks(this.active,seconds);this.active=[];}
 fadeTracks(tracks,seconds){if(!this.ctx)return;const now=this.ctx.currentTime;for(const track of tracks){const param=track.gain.gain,value=Atmosphere.hold(param,now);Atmosphere.ramp(param,value,0,now,seconds,false);try{track.source.stop(now+seconds+.025);}catch{}this.tails.add(track);setTimeout(()=>this.dispose(track),(seconds+.08)*1000);}}

 startLayers(prepared,seconds=1.6){const now=this.ctx.currentTime;for(const layer of prepared){const source=this.ctx.createBufferSource(),gain=this.ctx.createGain(),filter=this.ctx.createBiquadFilter();source.buffer=layer.buffer;source.loop=true;gain.gain.setValueAtTime(0,now);Atmosphere.ramp(gain.gain,0,this.ambient*layer.level,now,seconds,true);filter.type='lowpass';filter.frequency.value=layer.cutoff;source.connect(filter);filter.connect(gain);gain.connect(this.master);const track={source,gain,filter,name:layer.name,level:layer.level};source.onended=()=>this.dispose(track);source.start();this.active.push(track);}}
 reconcileLayers(prepared){const kept=[],fresh=[];for(const layer of prepared){const track=this.active.find(t=>t.name===layer.name);if(track){track.level=layer.level;Atmosphere.hold(track.gain.gain,this.ctx.currentTime);track.gain.gain.setTargetAtTime(this.ambient*layer.level,this.ctx.currentTime,.5);track.filter.frequency.setTargetAtTime(layer.cutoff,this.ctx.currentTime,.5);kept.push(track);}else fresh.push(layer);}const duration=Atmosphere.crossfadeSeconds();this.fadeTracks(this.active.filter(t=>!kept.includes(t)),duration);this.active=kept;this.startLayers(fresh,duration);}
 async beginChapter(scene){this.scene=scene;const token=++this.token;this.pendingScene=null;this.chapterChanging=true;this.stopEffects();if(!this.enabled||this.paused){this.chapterChanging=false;return;}try{await this.init();let desired,prepared;do{desired=this.scene;prepared=await this.prepare(desired);if(token!==this.token||!this.enabled||this.paused)return;}while(desired!==this.scene);this.reconcileLayers(prepared);this.playingScene=desired;this.onSceneChanged?.(desired);}catch(error){if(token===this.token)this.fail(error);}finally{if(token===this.token)this.chapterChanging=false;}}
 async setScene(scene,force=false){this.scene=scene;if(this.chapterChanging||!this.enabled||this.paused||!force&&(this.playingScene===scene||this.pendingScene===scene))return;const token=++this.token;this.pendingScene=scene;try{await this.init();const prepared=await this.prepare(scene);if(token!==this.token||!this.enabled||this.paused)return;this.reconcileLayers(prepared);this.playingScene=scene;this.onSceneChanged?.(scene);}catch(error){if(token===this.token)this.fail(error);}finally{if(token===this.token)this.pendingScene=null;}}
 async setEnabled(value){this.enabled=!!value;const token=++this.token;this.pendingScene=null;if(!value){this.chapterChanging=false;this.stopEffects();this.fadeOut(.3);await this.wait(380);if(token===this.token&&this.ctx&&!this.enabled)await this.ctx.suspend();return;}try{await this.init();await this.preloadEffects();if(token===this.token)await this.setScene(this.scene,true);}catch(error){this.fail(error);}}
 async pause(value){value=!!value;if(value===this.paused)return;this.paused=value;const token=++this.token;this.pendingScene=null;if(value){this.chapterChanging=false;this.stopEffects();this.fadeOut(.6);await this.wait(680);if(token===this.token&&this.paused&&this.ctx)await this.ctx.suspend();}else if(this.enabled){await this.init();if(token===this.token)await this.setScene(this.scene,true);}}
 preloadEffects(){return Promise.allSettled(['knock','glass','shot','impact'].map(name=>this.buffer(name)));}
 async cue(name,{isCurrent=()=>true,maxDelay=200}={}){if(!this.enabled||this.paused||!this.effectsEnabled)return false;const epoch=this.effectEpoch||0,requested=performance.now();try{await this.init();const buffer=await this.buffer(name);if(epoch!==(this.effectEpoch||0)||!this.enabled||this.paused||!this.effectsEnabled||performance.now()-requested>maxDelay||!isCurrent())return false;const source=this.ctx.createBufferSource(),gain=this.ctx.createGain();source.buffer=buffer;gain.gain.value=this.fx*(name==='shot'?.62:.85);source.connect(gain);gain.connect(this.master);this.effects.add(source);source.onended=()=>{this.effects.delete(source);gain.disconnect();};source.start();this.onCueStarted?.(name);return true;}catch{this.onError?.('Этот звуковой эффект недоступен.');return false;}}
 stopEffects(){this.effectEpoch=(this.effectEpoch||0)+1;for(const source of this.effects){try{source.stop();}catch{}}this.effects.clear();}
 fail(error){this.onFailure?.(error);this.enabled=false;this.chapterChanging=false;this.fadeOut(.2);this.onError?.('Не удалось включить звук. Проверьте аудиоустройство и попробуйте ещё раз.');}
}
if(typeof window!=='undefined')window.Atmosphere=Atmosphere;
if(typeof module!=='undefined')module.exports=Atmosphere;
